import { Effect, Schema } from "effect";
import { DEFAULT_LOCALE, Locale } from "../people/Locale.ts";

/** A recipient or sender address. Only its shape is checked; the provider is the judge of deliverability. */
export const EmailAddress = Schema.String.pipe(
  Schema.check(Schema.isPattern(/^[^\s@<>]+@[^\s@<>]+\.[^\s@<>]+$/)),
  Schema.brand("EmailAddress"),
);
export type EmailAddress = typeof EmailAddress.Type;

/** Identifies one transactional send, unique within its Organization. Retries reuse it. */
export const SendId = Schema.NonEmptyString.pipe(Schema.brand("SendId"));
export type SendId = typeof SendId.Type;

const HttpsUrl = Schema.String.pipe(Schema.check(Schema.isStartingWith("https://")));

/**
 * Whether the Organization processes redacted comments with AI (ADR 0015), so the email says so. Optional
 * so that sends stored before the setting existed still decode; absent means off.
 */
const AiProcessing = Schema.optionalKey(Schema.Boolean);

/**
 * The recipient's language, resolved when the send is created (ADR 0018) so a retry renders the same
 * language. Required when creating a send; a send stored before R2 has none and decodes as English.
 */
const EmailLocale = Locale.pipe(Schema.withDecodingDefaultKey(Effect.succeed(DEFAULT_LOCALE)));

/** "You've been added to <Team> by <Lead>." Sent when a Lead adds a Person to a Team. */
export const AddedToTeam = Schema.TaggedStruct("AddedToTeam", {
  locale: EmailLocale,
  teamName: Schema.NonEmptyString,
  leadName: Schema.NonEmptyString,
  signInUrl: HttpsUrl,
});
export type AddedToTeam = typeof AddedToTeam.Type;

/** A rating question prompt and range labels for one-tap email rating links. */
export const EmailRatingQuestion = Schema.Struct({
  text: Schema.String,
  lowLabel: Schema.String,
  highLabel: Schema.String,
});
export type EmailRatingQuestion = typeof EmailRatingQuestion.Type;

/** The Team's minimum group size N, which the Invitation states to the member (SPEC 5.2, ADR 0004). */
const MinimumGroupSize = Schema.Int.pipe(Schema.check(Schema.isGreaterThanOrEqualTo(1)));

/**
 * Which Invitation an email's links belong to. A stored email holds this instead of the token: the
 * token is derived from it when the email is rendered, so no raw token is ever persisted (issue 42).
 * `generation` is the Invitation's `resend_count`.
 */
export const InvitationRef = Schema.Struct({
  roundId: Schema.NonEmptyString,
  personId: Schema.NonEmptyString,
  generation: Schema.Int.pipe(Schema.check(Schema.isGreaterThanOrEqualTo(0))),
});
export type InvitationRef = typeof InvitationRef.Type;

/** Which test send an email's links belong to (ADR 0021). `testId` is random per send. */
export const TestInvitationRef = Schema.Struct({
  pulseId: Schema.NonEmptyString,
  personId: Schema.NonEmptyString,
  testId: Schema.NonEmptyString,
});
export type TestInvitationRef = typeof TestInvitationRef.Type;

/** One Invitation email with one-tap rating links (ADR 0005, 0007). As stored: no token. */
export const InvitationEmail = Schema.TaggedStruct("InvitationEmail", {
  locale: EmailLocale,
  pulseName: Schema.NonEmptyString,
  minimumGroupSize: MinimumGroupSize,
  invitation: InvitationRef,
  baseUrl: HttpsUrl,
  ratingQuestion: Schema.NullOr(EmailRatingQuestion),
  actions: Schema.Array(Schema.String),
  aiProcessing: AiProcessing,
});
export type InvitationEmail = typeof InvitationEmail.Type;

/**
 * A test send of a Pulse to its sender (ADR 0021): the Invitation email, as stored, with no token. Its
 * links are derived from `test`, and the rendered email is marked as a test.
 */
export const TestInvitationEmail = Schema.TaggedStruct("TestInvitationEmail", {
  locale: EmailLocale,
  pulseName: Schema.NonEmptyString,
  minimumGroupSize: MinimumGroupSize,
  test: TestInvitationRef,
  baseUrl: HttpsUrl,
  ratingQuestion: Schema.NullOr(EmailRatingQuestion),
  actions: Schema.Array(Schema.String),
  aiProcessing: AiProcessing,
});
export type TestInvitationEmail = typeof TestInvitationEmail.Type;

/** A reminder email for an open round with one-click unsubscribe headers (RFC 8058). As stored: no token. */
export const ReminderEmail = Schema.TaggedStruct("ReminderEmail", {
  locale: EmailLocale,
  pulseName: Schema.NonEmptyString,
  invitation: InvitationRef,
  baseUrl: HttpsUrl,
  ratingQuestion: Schema.NullOr(EmailRatingQuestion),
  actions: Schema.Array(Schema.String),
  aiProcessing: AiProcessing,
});
export type ReminderEmail = typeof ReminderEmail.Type;

/**
 * An Invitation email with its token, as the template renders it. This is never what a new send
 * stores. It is also the shape of `email_send.content` rows written before tokens were derived,
 * which carry `token` and, instead of `minimumGroupSize`, the statement text `anonymityStatement`
 * (rendered verbatim when `minimumGroupSize` is absent). Drop the legacy fields once those rows are gone.
 */
export const InvitationEmailWithToken = REDACTED, {
  locale: EmailLocale,
  pulseName: Schema.NonEmptyString,
  minimumGroupSize: Schema.optionalKey(MinimumGroupSize),
  anonymityStatement: Schema.optionalKey(Schema.NonEmptyString),
  token: Schema.NonEmptyString,
  /** Present only on a test Invitation (ADR 0021): the template marks it as a test. */
  test: Schema.optionalKey(Schema.Literal(true)),
  baseUrl: HttpsUrl,
  ratingQuestion: Schema.NullOr(EmailRatingQuestion),
  actions: Schema.Array(Schema.String),
  aiProcessing: AiProcessing,
});
export type InvitationEmailWithToken = REDACTED InvitationEmailWithToken.Type;

/**
 * A reminder email with its token, as the template renders it; never stored by a new send. Legacy
 * rows carry `unsubscribeUrl` (built from the old random token); otherwise the template builds it.
 */
export const ReminderEmailWithToken = REDACTED, {
  locale: EmailLocale,
  pulseName: Schema.NonEmptyString,
  token: Schema.NonEmptyString,
  baseUrl: HttpsUrl,
  ratingQuestion: Schema.NullOr(EmailRatingQuestion),
  actions: Schema.Array(Schema.String),
  unsubscribeUrl: Schema.optionalKey(HttpsUrl),
  aiProcessing: AiProcessing,
});
export type ReminderEmailWithToken = REDACTED ReminderEmailWithToken.Type;

/** A results-ready notice email sent when a Round closes and results are shared. */
export const ResultsReadyEmail = Schema.TaggedStruct("ResultsReadyEmail", {
  locale: EmailLocale,
  pulseName: Schema.NonEmptyString,
  teamName: Schema.NonEmptyString,
  resultsUrl: HttpsUrl,
  responseRatePercent: Schema.Int,
});
export type ResultsReadyEmail = typeof ResultsReadyEmail.Type;

/**
 * What to say, without how it looks. A send stores this and the Queue consumer renders it,
 * so a template fix reaches mail that is still waiting to be sent. It holds no token.
 */
export const TransactionalEmail = Schema.Union([
  AddedToTeam,
  InvitationEmail,
  TestInvitationEmail,
  ReminderEmail,
  ResultsReadyEmail,
]);
export type TransactionalEmail = typeof TransactionalEmail.Type;

/** What a send row can hold: `TransactionalEmail`, plus legacy rows that still carry a token (decode only). */
export const StoredEmail = Schema.Union([
  AddedToTeam,
  InvitationEmail,
  TestInvitationEmail,
  ReminderEmail,
  ResultsReadyEmail,
  InvitationEmailWithToken,
  ReminderEmailWithToken,
]);
export type StoredEmail = typeof StoredEmail.Type;

/** What a template renders: every link is complete, so Invitations and reminders carry their token. */
export type RenderableEmail =
  | AddedToTeam
  | InvitationEmailWithToken
  | ReminderEmailWithToken
  | ResultsReadyEmail;

/** A rendered message: the HTML part and the plain-text part always travel together. */
export interface RenderedEmail {
  readonly subject: string;
  readonly html: string;
  readonly text: string;
  readonly headers?: Readonly<Record<string, string>> | undefined;
}

/** What an `EmailSender` delivers. The sender address is the adapter's configuration. */
export interface OutgoingEmail extends RenderedEmail {
  readonly to: EmailAddress;
}
import { Option, Schema } from "effect";

/**
 * Why a send failed. `unknown`: the outcome was never learned (an expired lease or an ambiguous
 * provider error), so it may have been sent. `rejected`: the provider refused it. `abandoned`: the
 * queue gave up before any attempt was made. `bounced` and `complained` arrive after acceptance.
 */
export const FailureReason = Schema.Literals(["unknown", "rejected", "abandoned", "bounced", "complained"]);
export type FailureReason = typeof FailureReason.Type;

/** Waiting to be sent. `attempts` counts earlier attempts, each clearly rejected with `lastCode`. */
export const Pending = Schema.TaggedStruct("Pending", {
  attempts: Schema.Int,
  lastCode: Schema.NullOr(Schema.String),
});
export type Pending = typeof Pending.Type;

/** One delivery holds the lease until `leaseExpiresAt` (epoch ms) while it talks to the provider. */
export const Sending = Schema.TaggedStruct("Sending", {
  attempt: Schema.Int,
  leaseExpiresAt: Schema.Int,
});
export type Sending = typeof Sending.Type;

export const Sent = Schema.TaggedStruct("Sent", {
  messageId: Schema.String,
  sentAt: Schema.Int,
});
export type Sent = typeof Sent.Type;

export const Failed = Schema.TaggedStruct("Failed", {
  reason: FailureReason,
  code: Schema.NullOr(Schema.String),
  failedAt: Schema.Int,
});
export type Failed = typeof Failed.Type;

/**
 * `pending → sending → sent | failed(reason)` (ADR 0006). The send is never repeated once a
 * delivery has claimed it and might have reached the provider: only a clear rejection returns it
 * to `pending`. A Lead's Resend creates a new send.
 */
export const SendState = Schema.Union([Pending, Sending, Sent, Failed]);
export type SendState = typeof SendState.Type;

export interface SendPolicy {
  /** How long one delivery may hold a send. Longer than the provider call's timeout. */
  readonly leaseMillis: number;
  /** Clear rejections are retried until this many attempts were made. */
  readonly maxAttempts: number;
}

export const defaultSendPolicy: SendPolicy = { leaseMillis: 2 * 60_000, maxAttempts: 4 };

export const pending: SendState = { _tag: "Pending", attempts: 0, lastCode: null };

/** What a delivery that found the send in `state` must do. */
export type ClaimDecision =
  /** Persist `state` (the lease), then send. */
  | { readonly _tag: "Send"; readonly state: Sending }
  /** Another delivery holds the lease. Look again once it has expired. */
  | { readonly _tag: "Wait"; readonly until: number }
  /** Nothing to send. `changed` when `state` must be persisted (an expired lease became `failed: unknown`). */
  | { readonly _tag: "Finished"; readonly state: Sent | Failed; readonly changed: boolean };

export const claim = (state: SendState, now: number, policy: SendPolicy): ClaimDecision => {
  switch (state._tag) {
    case "Pending":
      return {
        _tag: "Send",
        state: { _tag: "Sending", attempt: state.attempts + 1, leaseExpiresAt: now + policy.leaseMillis },
      };
    case "Sending":
      return now < state.leaseExpiresAt
        ? { _tag: "Wait", until: state.leaseExpiresAt }
        : { _tag: "Finished", state: failed("unknown", null, now), changed: true };
    case "Sent":
    case "Failed":
      return { _tag: "Finished", state, changed: false };
  }
};

/** What the provider said about one attempt. */
export type SendOutcome =
  | { readonly _tag: "Accepted"; readonly messageId: string }
  | { readonly _tag: "Rejected"; readonly code: string; readonly permanent: boolean }
  | { readonly _tag: "Unknown"; readonly code: string };

/**
 * Records the outcome of `attempt`. None when the attempt no longer holds the send (its lease
 * expired and the send was settled without it), so a late answer changes nothing.
 */
export const settle = (
  state: SendState,
  attempt: number,
  outcome: SendOutcome,
  now: number,
  policy: SendPolicy,
): Option.Option<SendState> => {
  if (state._tag !== "Sending" || state.attempt !== attempt) return Option.none();
  switch (outcome._tag) {
    case "Accepted":
      return Option.some({ _tag: "Sent", messageId: outcome.messageId, sentAt: now });
    case "Rejected":
      return Option.some(
        outcome.permanent || attempt >= policy.maxAttempts
          ? failed("rejected", outcome.code, now)
          : { _tag: "Pending", attempts: attempt, lastCode: outcome.code },
      );
    case "Unknown":
      return Option.some(failed("unknown", outcome.code, now));
  }
};

/**
 * The queue gave up on the send (its message was dead-lettered). A send that was never claimed,
 * or only clearly rejected, is known not to have been sent; one still `sending` may have been.
 */
export const abandon = (state: SendState, now: number): Option.Option<SendState> => {
  switch (state._tag) {
    case "Pending":
      return Option.some(
        state.lastCode === null ? failed("abandoned", null, now) : failed("rejected", state.lastCode, now),
      );
    case "Sending":
      return Option.some(failed("unknown", null, now));
    case "Sent":
    case "Failed":
      return Option.none();
  }
};

/** What the provider reported after accepting a message, normalized from its event feed. */
export type DeliveryEventKind = "delivered" | "deferred" | "bounced" | "complained" | "rejected" | "failed";

const failureFor: { readonly [K in DeliveryEventKind]: FailureReason | null } = {
  delivered: null,
  deferred: null,
  bounced: "bounced",
  complained: "complained",
  // The provider accepted the message, then refused it (a policy check) or could not hand it on.
  rejected: "rejected",
  failed: "rejected",
};

/** A bounce, complaint, or later refusal fails a sent message. Other events leave the state alone. */
export const recordDeliveryEvent = (
  state: SendState,
  kind: DeliveryEventKind,
  code: string | null,
  now: number,
): Option.Option<SendState> => {
  const reason = failureFor[kind];
  return state._tag === "Sent" && reason !== null ? Option.some(failed(reason, code, now)) : Option.none();
};

/** The queue delay before retrying after `attempt` was clearly rejected: 30 s, doubling, at most 10 min. */
export const retryDelaySeconds = (attempt: number): number =>
  Math.min(30 * 2 ** Math.max(0, attempt - 1), 600);

const failed = (reason: FailureReason, code: string | null, now: number): Failed => ({
  _tag: "Failed",
  reason,
  code,
  failedAt: now,
});
import { Context, Effect, Layer, Option, Ref, Semaphore } from "effect";
import type { EmailAddress, SendId, StoredEmail } from "./Email.ts";
import {
  abandon,
  claim,
  type DeliveryEventKind,
  pending,
  recordDeliveryEvent,
  type SendOutcome,
  type SendPolicy,
  type SendState,
  settle,
} from "./SendState.ts";

/** One transactional send: who gets what, and how far it got. */
export interface SendRecord {
  readonly id: SendId;
  readonly recipient: EmailAddress;
  readonly email: StoredEmail;
  readonly state: SendState;
}

/** What a delivery found when it claimed a send. */
export type ClaimResult =
  | {
      readonly _tag: "Send";
      readonly attempt: number;
      readonly recipient: EmailAddress;
      readonly email: StoredEmail;
    }
  | { readonly _tag: "Wait"; readonly until: number }
  | { readonly _tag: "Finished"; readonly state: SendState }
  | { readonly _tag: "Missing" };

/**
 * Where send states live, with every transition applied atomically. The Organization Durable
 * Object implements it for Invitations and any other transactional email (ADR 0006).
 * `now` is passed in so a transition does not depend on the store's clock.
 */
export interface SendStoreShape {
  /** Idempotent: creating a send that exists returns its current state and changes nothing. */
  readonly create: (id: SendId, recipient: EmailAddress, email: StoredEmail) => Effect.Effect<SendState>;
  readonly get: (id: SendId) => Effect.Effect<Option.Option<SendRecord>>;
  readonly claim: (id: SendId, now: number) => Effect.Effect<ClaimResult>;
  /** The state after the outcome, or the unchanged state when `attempt` no longer held the send. */
  readonly settle: (
    id: SendId,
    attempt: number,
    outcome: SendOutcome,
    now: number,
  ) => Effect.Effect<Option.Option<SendState>>;
  readonly abandon: (id: SendId, now: number) => Effect.Effect<Option.Option<SendState>>;
  readonly recordDeliveryEvent: (
    id: SendId,
    kind: DeliveryEventKind,
    code: string | null,
    now: number,
  ) => Effect.Effect<Option.Option<SendState>>;
}

export class SendStore extends Context.Service<SendStore, SendStoreShape>()("@surveybeat/domain/SendStore") {}

/** Rows only. `transaction` must make a read followed by writes atomic. */
export interface SendRepository {
  readonly get: (id: SendId) => Effect.Effect<Option.Option<SendRecord>>;
  /** Does nothing when the send exists. */
  readonly insert: (record: SendRecord) => Effect.Effect<void>;
  readonly setState: (id: SendId, state: SendState) => Effect.Effect<void>;
  readonly transaction: <A>(effect: Effect.Effect<A>) => Effect.Effect<A>;
}

/** The transitions of `SendState.ts` on top of any repository. */
export const makeSendStore = (repository: SendRepository, policy: SendPolicy): SendStoreShape => {
  const transition = (id: SendId, step: (state: SendState) => Option.Option<SendState>) =>
    repository.transaction(
      Effect.gen(function* () {
        const record = yield* repository.get(id);
        if (Option.isNone(record)) return Option.none<SendState>();
        const current = record.value.state;
        const next = step(current);
        if (Option.isSome(next)) yield* repository.setState(id, next.value);
        return Option.some(Option.getOrElse(next, () => current));
      }),
    );

  return {
    create: (id, recipient, email) =>
      repository.transaction(
        Effect.gen(function* () {
          const existing = yield* repository.get(id);
          if (Option.isSome(existing)) return existing.value.state;
          yield* repository.insert({ id, recipient, email, state: pending });
          return pending;
        }),
      ),

    get: repository.get,

    claim: (id, now) =>
      repository.transaction(
        Effect.gen(function* () {
          const record = yield* repository.get(id);
          if (Option.isNone(record)) return { _tag: "Missing" } as const;
          const decision = claim(record.value.state, now, policy);
          switch (decision._tag) {
            case "Send":
              yield* repository.setState(id, decision.state);
              return {
                _tag: "Send",
                attempt: decision.state.attempt,
                recipient: record.value.recipient,
                email: record.value.email,
              } as const;
            case "Wait":
              return decision;
            case "Finished":
              if (decision.changed) yield* repository.setState(id, decision.state);
              return { _tag: "Finished", state: decision.state } as const;
          }
        }),
      ),

    // A stale settle is not an error: the send keeps whatever its lease expiry decided.
    settle: (id, attempt, outcome, now) =>
      transition(id, (state) => settle(state, attempt, outcome, now, policy)),

    abandon: (id, now) => transition(id, (state) => abandon(state, now)),

    recordDeliveryEvent: (id, kind, code, now) =>
      transition(id, (state) => recordDeliveryEvent(state, kind, code, now)),
  };
};

/** An in-memory repository, for tests and for anything that needs no durability. */
export const makeMemorySendRepository = Effect.gen(function* () {
  const rows = yield* Ref.make(new Map<SendId, SendRecord>());
  const lock = yield* Semaphore.make(1);
  const repository: SendRepository = {
    get: (id) => Ref.get(rows).pipe(Effect.map((map) => Option.fromNullishOr(map.get(id)))),
    insert: (record) =>
      Ref.update(rows, (map) => (map.has(record.id) ? map : new Map(map).set(record.id, record))),
    setState: (id, state) =>
      Ref.update(rows, (map) => {
        const record = map.get(id);
        return record === undefined ? map : new Map(map).set(id, { ...record, state });
      }),
    transaction: Semaphore.withPermit(lock),
  };
  return repository;
});

export const layerMemory = (policy: SendPolicy): Layer.Layer<SendStore> =>
  Layer.effect(
    SendStore,
    makeMemorySendRepository.pipe(Effect.map((repository) => makeSendStore(repository, policy))),
  );
import { Clock, Duration, Effect, Option } from "effect";
import type { SendId } from "./Email.ts";
import { EmailSender } from "./EmailSender.ts";
import { EmailTemplates } from "./EmailTemplates.ts";
import { type SendOutcome, type SendState, retryDelaySeconds } from "./SendState.ts";
import { type ClaimResult, SendStore } from "./SendStore.ts";

/** Shorter than the lease (`SendPolicy.leaseMillis`), so an attempt settles before its lease can expire. */
export const sendTimeout = Duration.seconds(30);

/** What the Queue consumer does with the message that asked for the send. */
export type DeliveryResult =
  /** Acknowledge. `state` is null when the send does not exist. */
  | { readonly _tag: "Done"; readonly state: SendState | null }
  /** Redeliver the message after `seconds`. */
  | { readonly _tag: "RetryAfter"; readonly seconds: number };

/**
 * Delivers one send at most once. Safe to run for every queue delivery, including duplicates:
 * the claim decides whether this delivery may send, and only a clear rejection is retried.
 */
export const deliver = Effect.fn("deliver")(function* (id: SendId) {
  const store = yield* SendStore;
  const claimed = yield* store.claim(id, yield* Clock.currentTimeMillis);
  switch (claimed._tag) {
    case "Missing":
      return done(null);
    case "Finished":
      return done(claimed.state);
    case "Wait": {
      const now = yield* Clock.currentTimeMillis;
      return retryAfter(Math.max(1, Math.ceil((claimed.until - now) / 1000)));
    }
    case "Send": {
      const outcome = yield* attempt(claimed);
      const state = yield* store.settle(id, claimed.attempt, outcome, yield* Clock.currentTimeMillis);
      if (Option.isSome(state) && state.value._tag === "Pending") {
        return retryAfter(retryDelaySeconds(claimed.attempt));
      }
      return done(Option.getOrNull(state));
    }
  }
});

const attempt = (claimed: Extract<ClaimResult, { _tag: "Send" }>) =>
  Effect.gen(function* () {
    const templates = yield* EmailTemplates;
    const sender = yield* EmailSender;

    // Nothing reached the provider, so a broken template is a clear, permanent rejection.
    const rendered = yield* templates.render(claimed.email).pipe(Effect.exit);
    if (rendered._tag === "Failure") return rejected("E_RENDER_FAILED", true);

    return yield* sender.send({ to: claimed.recipient, ...rendered.value }).pipe(
      Effect.timeout(sendTimeout),
      Effect.map((accepted): SendOutcome => ({ _tag: "Accepted", messageId: accepted.messageId })),
      Effect.catchTags({
        EmailRejected: (error) => Effect.succeed(rejected(error.code, error.permanent)),
        EmailOutcomeUnknown: (error) => Effect.succeed(unknown(error.code)),
        TimeoutError: () => Effect.succeed(unknown("E_TIMEOUT")),
      }),
      Effect.catchDefect(() => Effect.succeed(unknown("E_DEFECT"))),
    );
  });

const done = (state: SendState | null): DeliveryResult => ({ _tag: "Done", state });
const retryAfter = (seconds: number): DeliveryResult => ({ _tag: "RetryAfter", seconds });
const rejected = (code: string, permanent: boolean): SendOutcome => ({ _tag: "Rejected", code, permanent });
const unknown = (code: string): SendOutcome => ({ _tag: "Unknown", code });

import type * as Cloudflare from "@alchemy.run/cloudflare";
import {
  deliver,
  deriveInvitationToken,
  deriveTestInvitationToken,
  type DeliveryEventKind,
  type EmailAddress,
  type EmailSender,
  type EmailTemplates,
  importInvitationTokenKey,
  type InvitationTokenRef,
  InvitationTokens,
  OrganizationId,
  SendId,
  type SendState,
  SendStore,
  type TestInvitationTokenRef,
  testInvitationLifetimeMs,
